printf '%s\n' 'import argparse' 'import json' 'import sys' '' 'p = argparse.ArgumentParser()' 'p.add_argument("config")' 'p.add_argument("--env", choices=["dev", "staging", "prod"], default="dev")' 'a = p.parse_args()' 'try:' '    cfg = json.load(open(a.config))' 'except (OSError, ValueError):' '    sys.exit("error: cannot read config")' 'for k in ("app", "defaults"):' '    if k not in cfg:' '        sys.exit("error: missing key: " + k)' 'settings = dict(cfg["defaults"])' 'settings.update(cfg.get("environments", {}).get(a.env, {}))' 'print(json.dumps(settings, indent=4, sort_keys=True))' > build_config.py
